#[tokio::test]
async fn adopting_a_policy_then_requesting_an_export_redacts_internal_identifiers() {
    let Ok(database_url) = std::env::var("ACKPLANE_TEST_DATABASE_URL") else {
        println!("skipped: ACKPLANE_TEST_DATABASE_URL not set");
        return;
    };
    let suffix = unique_suffix();
    let tenant_id = format!("tenant-administration-export-{suffix}");
    let repository_id = format!("repository-administration-export-{suffix}");
    enroll_repository(&database_url, &tenant_id, &repository_id, &suffix).await;
    insert_telemetry_event(
        &database_url,
        &tenant_id,
        &repository_id,
        &format!("event-{suffix}"),
    )
    .await;

    let fleet = Arc::new(
        FleetStore::connect(&database_url)
            .await
            .expect("the test database should accept Fleet connections"),
    );
    let administration = AdministrationStore::connect(&database_url)
        .await
        .expect("the test database should accept Administration store connections");
    let dir = std::env::temp_dir().join(format!("ackplane-export-integration-{suffix}"));
    let _ = std::fs::remove_dir_all(&dir);
    let state = AdministrationApiState::new(
        fleet,
        Arc::from(tenant_id.clone()),
        Arc::new(Mutex::new(administration)),
        None,
        Some(Arc::new(ExportProviderConfig {
            database_url: database_url.clone(),
            export_dir: dir.clone(),
        })),
    );
    let router = administration_routes(state);

    // No adopted policy yet: refused before any request row exists.
    let (refused_status, refused_body) = post_json(
        &router,
        &format!("/api/v1/repositories/{repository_id}/administration/exports"),
        json!({
            "policy_id": format!("administration-policy:does-not-exist-{suffix}"),
            "data_category": "telemetry_events",
            "purpose": "quarterly diagnostic telemetry audit",
            "max_records": 100,
            "idempotency_key": format!("export-{suffix}"),
        }),
    )
    .await;
    assert_eq!(
        refused_status,
        StatusCode::CONFLICT,
        "body was {refused_body:?}"
    );

    let (policy_status, policy_body) = post_json(
        &router,
        "/api/v1/administration/policies",
        json!({
            "operation": "export",
            "scope": "tenant",
            "tenant_id": tenant_id,
            "data_classification": "diagnostic-telemetry",
            "retention_basis": "named audit export, ADR-0119 decision 5",
            "idempotency_key": format!("export-policy-{suffix}"),
            "lifetime_seconds": 3600,
        }),
    )
    .await;
    assert_eq!(policy_status, StatusCode::OK, "body was {policy_body:?}");
    let policy_id = policy_body["policy_id"]
        .as_str()
        .expect("the response should carry a policy_id")
        .to_string();

    let (export_status, export_body) = post_json(
        &router,
        &format!("/api/v1/repositories/{repository_id}/administration/exports"),
        json!({
            "policy_id": policy_id,
            "data_category": "telemetry_events",
            "purpose": "quarterly diagnostic telemetry audit",
            "max_records": 100,
            "idempotency_key": format!("export-{suffix}"),
        }),
    )
    .await;
    assert_eq!(export_status, StatusCode::OK, "body was {export_body:?}");
    assert_eq!(export_body["receipt"]["outcome"], json!("succeeded"));
    assert_eq!(export_body["receipt"]["record_count"], json!(1));
    assert_eq!(
        export_body["receipt"]["redacted_fields"],
        json!(["telemetry_id", "node_id", "agent_session_id"])
    );
    let request_id = export_body["request_id"]
        .as_str()
        .expect("the response should carry a request_id")
        .to_string();

    // A replay of the exact same request must not run the export query a
    // second time; it returns the original receipt and says so.
    let (replay_status, replay_body) = post_json(
        &router,
        &format!("/api/v1/repositories/{repository_id}/administration/exports"),
        json!({
            "policy_id": policy_id,
            "data_category": "telemetry_events",
            "purpose": "quarterly diagnostic telemetry audit",
            "max_records": 100,
            "idempotency_key": format!("export-{suffix}"),
        }),
    )
    .await;
    assert_eq!(replay_status, StatusCode::OK, "body was {replay_body:?}");
    assert_eq!(replay_body["idempotent_replay"], json!(true));
    assert_eq!(
        replay_body["receipt"]["receipt_id"],
        export_body["receipt"]["receipt_id"]
    );

    let artifact_path = export_body["receipt"]["artifact_path"]
        .as_str()
        .expect("a succeeded export should carry an artifact path");
    let artifact_body =
        std::fs::read_to_string(artifact_path).expect("the export artifact file should exist");
    assert!(!artifact_body.contains("a-node-id"));
    assert!(!artifact_body.contains("a-session-id"));
    assert!(artifact_body.contains("a-tool-name"));

    let (status_status, status_body) = get_json(
        &router,
        &format!("/api/v1/repositories/{repository_id}/administration/exports/{request_id}"),
    )
    .await;
    assert_eq!(status_status, StatusCode::OK, "body was {status_body:?}");
    assert_eq!(
        status_body["receipt_id"],
        export_body["receipt"]["receipt_id"]
    );

    // A different tenant must not read this receipt back merely by knowing
    // (or guessing) the request id.
    let foreign_administration = AdministrationStore::connect(&database_url)
        .await
        .expect("the test database should accept Administration store connections");
    let foreign_router = administration_routes(AdministrationApiState::new(
        Arc::new(
            FleetStore::connect(&database_url)
                .await
                .expect("the test database should accept Fleet connections"),
        ),
        Arc::from(format!("foreign-{tenant_id}")),
        Arc::new(Mutex::new(foreign_administration)),
        None,
        None,
    ));
    let foreign_response = foreign_router
        .oneshot(
            Request::builder()
                .uri(format!(
                    "/api/v1/repositories/{repository_id}/administration/exports/{request_id}"
                ))
                .body(Body::empty())
                .expect("the foreign request should build"),
        )
        .await
        .expect("the foreign request should receive a response");
    assert_eq!(foreign_response.status(), StatusCode::NOT_FOUND);

    let _ = std::fs::remove_dir_all(&dir);
}
